namespace Gordic.Ada.WebClient {

    var gcontent = Decorators.gcontent;

    @gcontent

    export class GAkceSouvisejiciDetail extends GContentBase implements IGContent {

        public AkceFiltrDto: Gordic.Ada.Interface.GAgDokladyFilterDto;
        public modelSou: Gordic.Ada.Interface.GSrvscisDto;
//        private globals = Gordic.Ada.Globals.GAdaGlobals;
        private readonly globals: Gordic.Ada.WebClient.DTO.GAdaGlobalsDto;

        //---------------------------------------------------------------
        // Inicializace formuláře
        onContentReady() {

            var that = this;

            that.actions.addRange({                                                                                     // přidání akcí

                actOK: {
                    caption: "Ok",                                                                                      // OK
                    icon: "",                                                                                           // ikona 
                    visible: (that.globals.Param_Akce_Editace_TP!), //true,                                                                                      // vždy viditelné
                    enabled: (that.globals.Param_Akce_Editace_TP!),
                    run: function () {
                        that.closing(true) 
                    }
                },
                actZrusit: {
                    caption: "Zrušit",                                                                                  // popis
                    icon: "gi-window-close",                                                                            // ikona 
                    visible: true,                                                                                      // vždy viditelné
                    enabled: true,                                                                                      // vždy spustitelné
                    run: function () {
                        that.closing(false) 
                    }
                }
            });

            //*******************************************************
            // P ř i d á v á n í   a k c í   d o   m e n u   b a r u
            this.menuBar([

            ]);
            this.commandBar([
                { action: that.actions.actOK, favorite: true, primary: true },                                                         // Ok
                { action: that.actions.actZrusit, favorite: true },                                                     // Zrušit
            ]);

            // *****************************
            //    Formulář tabu
            var detailSouForm = new Gordic.Forms.Form({ name: "detailSOU", layoutDescriptor: "L4M4S2 L-3-9-0 M-3-9-0 S-12-12-0" })
                .addRow({ label: that.globals.BAR_Typ_Inst == Interface.SrvTypIntalaceEnum.MO ? "Číslo PP" : "Číslo akce" }).addField("gstringbox", "w-12", { disabled: true, name: "cislo" })
                .addRow({ label: that.globals.BAR_Typ_Inst == Interface.SrvTypIntalaceEnum.MO ? "Číslo PP - hist." : "Číslo akce - hist" }).addField("gstringbox", "w-12", { disabled: (that.modelSou.cislo_old == "" ? false : true), name: "cislo_old" })
                .addRow("Rok").addField("gnumberbox", "w-12", { disabled: (that.modelSou.cislo_old == "" ? false : true), name: "rok_od", validators: [new Gordic.Validators.Required(), new Gordic.Validators.Range({ min: 1900, max: 2050, message: "Chybně zadaná hodnota" })] })
                .addRow("Aktivita").addField("gselectbox", Gordic.Prefabs.Select.gincakt(), { name: "aktivita", dropdown: true, model: "model.aktivita = value.aktivita", serverFilters: { aktivita: [100, 500] }, validators: [new Gordic.Validators.Required()] })
                // hledani obsahuje .addRow("Aktivita").addField("gselectbox", Gordic.Prefabs.Select.gincakt(AdaFunction.zjisti_sloupce_search_array((Gordic.Prefabs.Select.gincakt().data as Gordic.Data.Readers.Gincakt).columns)), { name: "aktivita", dropdown: true, model: "model.aktivita = value.aktivita", serverFilters: { aktivita: [100, 500] }, validators: [new Gordic.Validators.Required()] })
                ;
            
            $("<div class='js-detailSou'>").appendTo(that.element).gform("createFrom", detailSouForm, ).findFields().gfield("model", "apply", that.modelSou);
            //that.findFields(".ui-tucne").find("input").addClass("bold");

            if (!that.globals.Param_Akce_Editace_TP) {
                var fields = this.findFields(); // všechny políčka
                fields.findFields().gfield("option", "disabled", true) // vždy enabled
            }

         };

        //---------------------------------------------------------------
        // Zavírání formuláře
        closing( provest ) {
            if (provest == true) {
                var $cDiv = $(this.contentDiv);
                //this.contentDiv.showFlash({ label: 'Ukladam akci ' + cislo });
                if ($cDiv.findForms().gform("isValid", true)) {
                    //var dto = {};
                    $cDiv.findFields().gfield("model", "collect", this.modelSou);
                    $cDiv.findFields().gfield("confirm");

                    this.close({ data: this.modelSou });                                  // při zavírání posílanám zpět objekt
                }
            }
            else {
                this.close({ data: null });                                  // při zavírání posílanám zpět objekt
            }
        }
    }
}